/* mesh.h version 1.0 -- the tile controller's view of the mesh sorter (spec/machine-spec.md v1.0: 4.10-4.12, 6, 8).
 * GENERATED by meshsim v1.0 (src/Registers.java); do not edit. The programmer's reference is sw/REGISTERS.md,
 * the conventions sw/CONVENTIONS.md. C and assembly: assembly sees only the #defines (__ASSEMBLER__). */
#ifndef MESH_H
#define MESH_H
#define MESH_H_VERSION 0x0100   /* 1.0: major << 8 | minor */

/* ---- address map (4.11) ---- */
#define IMEM_BASE            0   /* instruction memory, 8 KB (fetch only; port B: mode 5) */
#define IMEM_SIZE            0x2000
#define LOADER_BASE          0x1F00   /* resident loader, 64 words; HALT -> RUN starts here */
#define TABLE_BASE           0x2000   /* table window (4.10): word accesses only */
#define HIST_BASE            0x2000   /* HIST[256], 17 bits, read/write */
#define PTR_BASE             0x2400   /* PTR[256], 20 bits, write-only (a load is a bus error) */
#define STREAM_BASE          0x2800   /* STREAM[256], two words each (low, high); write-only (a load is a bus error) */
#define GROUP_BASE           0x3000   /* GROUP[64], two words each (low, high); write-only (a load is a bus error) */
#define DMEM_BASE            0x4000   /* data memory, 8 KB */
#define DMEM_SIZE            0x2000
#define MAILBOX_BASE         0x5C00   /* 256 x 32-bit slots, the top 1 KB of data memory (mode 6 only) */
#define STACK_TOP            0x5C00   /* the stack grows down from below the mailbox */

/* packed controller-memory word map (mode-5/7 addr, STREAM_LO.CM): words 0x000-0x7FF instruction, 0x800-0xFFF data */
#define CM_WORD(byte_addr) (((byte_addr) < DMEM_BASE) ? ((byte_addr) >> 2) : (0x800 + (((byte_addr) - DMEM_BASE) >> 2)))
#define MBOX_WORD            0xF00   /* packed word of mailbox slot 0 */

/* ---- registers (8): each one lw/sw with rs1 = x0 ---- */
#define TILE_STATUS_ADDR             0xFFFFF800   /* R: live bits, tile index, big-SRAM size (8.3); read-only */
#define TILE_CONDITIONS_ADDR         0xFFFFF804   /* R: the error conditions (4.13, 8.3a): bit n = condition n (TILE_COND_*); read-only, cleared only on entering HALT */
#define ROUTER_SET_HDR_ADDR          0xFFFFF808   /* W: dst, mode, addr of outgoing packets; addr += 2 (mode 5) or 1 (modes 6, 7) at each send */
#define ROUTER_SET_HI_ADDR           0xFFFFF80C   /* W: high 32 bits of the next payload; cleared to 0 by each send */
#define ROUTER_SEND_LO_ADDR          0xFFFFF810   /* W: low 32 bits; sends (stalls while the holding register is occupied and not being injected) */
#define DMA_CONFIG_ADDR              0xFFFFF814   /* W: the engine run, digits, k (8.1); write-only, reads 0 */
#define DMA_PULSE_ADDR               0xFFFFF818   /* W: 1 fires: [0] done [1] start ([3:2] reserved, ignored); start acts before done (8.2) */
#define DMA_SRAM_REMAINING_ADDR      0xFFFFF81C   /* RW: down-counter, modes 2, 3 and 4 (4.12); a store clears the local-wake latch */
#define DMA_CM_REMAINING_ADDR        0xFFFFF820   /* RW: down-counter, mode 5; a store clears the local-wake latch */
#define DMA_REPLY_REMAINING_ADDR     0xFFFFF824   /* RW: down-counter, mode 7; a store clears the local-wake latch */
#define DMA_RECORD_BASE_ADDRESS_ADDR 0xFFFFF828   /* W: 20-bit chunk address of the run's records: augment ordinal = (landing chunk - base) / 2 (4.9); gather address = base + 2k ordinal (4.4) */
#define SRAM_RD_ADDR_QUEUE_ADDR      0xFFFFF82C   /* RW: read port (4.3): write queues a 32-bit read of a 20-bit chunk address (never stalls); read = free entries */
#define SRAM_RD_DEST_ADDR_ADDR       0xFFFFF830   /* W: read port: packed data-memory word for the next result; +1 per queued read */

/* ---- fields: NAME_SHIFT, NAME_MASK (unshifted), NAME(v) placed ---- */

#define DMA_CFG_KIND_SHIFT       0
#define DMA_CFG_KIND_MASK        0x1   /* run kind: 0 stream run, 1 group run */
#define DMA_CFG_KIND(v)          (((unsigned)(v) & 0x1) << 0)
#define DMA_CFG_START_SHIFT      1
#define DMA_CFG_START_MASK       0xFF   /* first stream (0-255) or first GROUP entry (0-63) */
#define DMA_CFG_START(v)         (((unsigned)(v) & 0xFF) << 1)
#define DMA_CFG_COUNT_SHIFT      9
#define DMA_CFG_COUNT_MASK       0x1FF   /* streams (1-256) or groups (1-64) */
#define DMA_CFG_COUNT(v)         (((unsigned)(v) & 0x1FF) << 9)
#define DMA_CFG_BUCKETDIG_SHIFT  18
#define DMA_CFG_BUCKETDIG_MASK   0x7   /* bucket digit (mode 3): 0 none, 1-4 key byte, 1 least significant */
#define DMA_CFG_BUCKETDIG(v)     (((unsigned)(v) & 0x7) << 18)
#define DMA_CFG_HISTDIG_SHIFT    21
#define DMA_CFG_HISTDIG_MASK     0x7   /* histogram digit (count-on-arrival): 0 off, 1-4 */
#define DMA_CFG_HISTDIG(v)       (((unsigned)(v) & 0x7) << 21)
#define DMA_CFG_KM1_SHIFT        24
#define DMA_CFG_KM1_MASK         0x7   /* gather value size k - 1, in records */
#define DMA_CFG_KM1(v)           (((unsigned)(v) & 0x7) << 24)

#define DMA_PULSE_DONE_SHIFT     0
#define DMA_PULSE_DONE_MASK      0x1   /* done (READY fires when a command has landed) */
#define DMA_PULSE_DONE(v)        (((unsigned)(v) & 0x1) << 0)
#define DMA_PULSE_START_SHIFT    1
#define DMA_PULSE_START_MASK     0x1   /* start: load the run from DMA_CONFIG and begin it (the first request when its table entries are in) */
#define DMA_PULSE_START(v)       (((unsigned)(v) & 0x1) << 1)

#define TILE_ST_RD_RUNNING_SHIFT 0
#define TILE_ST_RD_RUNNING_MASK  0x1   /* live: the address generator is running (from the start, lead-in included) */
#define TILE_ST_RD_RUNNING(v)    (((unsigned)(v) & 0x1) << 0)
#define TILE_ST_RD_DONE_SHIFT    1
#define TILE_ST_RD_DONE_MASK     0x1   /* live: the last run has walked its last entry (cleared by the next start) */
#define TILE_ST_RD_DONE(v)       (((unsigned)(v) & 0x1) << 1)
#define TILE_ST_SEND_BUSY_SHIFT  3
#define TILE_ST_SEND_BUSY_MASK   0x1   /* live: the send holding register is occupied */
#define TILE_ST_SEND_BUSY(v)     (((unsigned)(v) & 0x1) << 3)
#define TILE_ST_TS_BUSY_SHIFT    4
#define TILE_ST_TS_BUSY_MASK     0x1   /* live: a table memory is in use by an engine */
#define TILE_ST_TS_BUSY(v)       (((unsigned)(v) & 0x1) << 4)
#define TILE_ST_MEM_IDLE_SHIFT   5
#define TILE_ST_MEM_IDLE_MASK    0x1   /* live: the big-SRAM write path is empty */
#define TILE_ST_MEM_IDLE(v)      (((unsigned)(v) & 0x1) << 5)
#define TILE_ST_CM_IDLE_SHIFT    6
#define TILE_ST_CM_IDLE_MASK     0x1   /* live: the port-B pipeline is empty */
#define TILE_ST_CM_IDLE(v)       (((unsigned)(v) & 0x1) << 6)
#define TILE_ST_DONE_SHIFT       7
#define TILE_ST_DONE_MASK        0x1   /* live: done */
#define TILE_ST_DONE(v)          (((unsigned)(v) & 0x1) << 7)
#define TILE_ST_LANDED_SHIFT     8
#define TILE_ST_LANDED_MASK      0x1   /* live: command landed */
#define TILE_ST_LANDED(v)        (((unsigned)(v) & 0x1) << 8)
#define TILE_ST_GATHER_BUSY_SHIFT 9
#define TILE_ST_GATHER_BUSY_MASK 0x1   /* live: the GATHER engine has work */
#define TILE_ST_GATHER_BUSY(v)   (((unsigned)(v) & 0x1) << 9)
#define TILE_ST_TILE_SHIFT       21
#define TILE_ST_TILE_MASK        0x3F   /* tile index */
#define TILE_ST_TILE(v)          (((unsigned)(v) & 0x3F) << 21)
#define TILE_ST_SIZE_SHIFT       29
#define TILE_ST_SIZE_MASK        0x7   /* big-SRAM size in 512 KB areas - 1 */
#define TILE_ST_SIZE(v)          (((unsigned)(v) & 0x7) << 29)

#define ROUTER_HDR_DST_SHIFT     0
#define ROUTER_HDR_DST_MASK      0x7F   /* destination: tile 0-63, 64 C&C, 126 broadcast */
#define ROUTER_HDR_DST(v)        (((unsigned)(v) & 0x7F) << 0)
#define ROUTER_HDR_MODE_SHIFT    7
#define ROUTER_HDR_MODE_MASK     0xF   /* packet mode (4 bits) */
#define ROUTER_HDR_MODE(v)       (((unsigned)(v) & 0xF) << 7)
#define ROUTER_HDR_ADDR_SHIFT    11
#define ROUTER_HDR_ADDR_MASK     0xFFFFF   /* address field */
#define ROUTER_HDR_ADDR(v)       (((unsigned)(v) & 0xFFFFF) << 11)

#define STREAM_LO_SRC_SHIFT      0
#define STREAM_LO_SRC_MASK       0xFFFFF   /* source chunk address */
#define STREAM_LO_SRC(v)         (((unsigned)(v) & 0xFFFFF) << 0)
#define STREAM_LO_CM_SHIFT       20
#define STREAM_LO_CM_MASK        0xFFF   /* controller-memory word, packed map (mode 5: destination) */
#define STREAM_LO_CM(v)          (((unsigned)(v) & 0xFFF) << 20)

#define STREAM_HI_COUNT_SHIFT    0
#define STREAM_HI_COUNT_MASK     0x3FFFF   /* elements */
#define STREAM_HI_COUNT(v)       (((unsigned)(v) & 0x3FFFF) << 0)
#define STREAM_HI_D_SHIFT        18
#define STREAM_HI_D_MASK         0x3F   /* destination offset: dst = (me + d) mod 64 */
#define STREAM_HI_D(v)           (((unsigned)(v) & 0x3F) << 18)
#define STREAM_HI_MODE_SHIFT     24
#define STREAM_HI_MODE_MASK      0x7   /* packet mode, zero-extended to 4 bits: 1-5 (0, 6, 7 reserved) */
#define STREAM_HI_MODE(v)        (((unsigned)(v) & 0x7) << 24)
#define STREAM_HI_SIZE_SHIFT     27
#define STREAM_HI_SIZE_MASK      0x3   /* read size: 1 32-bit, 2 64-bit, 3 128-bit (0 reserved) */
#define STREAM_HI_SIZE(v)        (((unsigned)(v) & 0x3) << 27)
#define STREAM_HI_GAP_SHIFT      29
#define STREAM_HI_GAP_MASK       0x7   /* gap after, cycles */
#define STREAM_HI_GAP(v)         (((unsigned)(v) & 0x7) << 29)

#define GROUP_LO_R_SHIFT         0
#define GROUP_LO_R_MASK          0x3FFFF   /* rotations */
#define GROUP_LO_R(v)            (((unsigned)(v) & 0x3FFFF) << 0)

#define GROUP_HI_START_SHIFT     0
#define GROUP_HI_START_MASK      0xFF   /* first stream */
#define GROUP_HI_START(v)        (((unsigned)(v) & 0xFF) << 0)
#define GROUP_HI_TM1_SHIFT       8
#define GROUP_HI_TM1_MASK        0xF   /* streams in the group - 1 */
#define GROUP_HI_TM1(v)          (((unsigned)(v) & 0xF) << 8)
#define GROUP_HI_GAP_SHIFT       12
#define GROUP_HI_GAP_MASK        0xFF   /* gap after the group, cycles */
#define GROUP_HI_GAP(v)          (((unsigned)(v) & 0xFF) << 12)

#define AREA_CHUNKS_SHIFT    17   /* chunks per 512 KB big-SRAM area, log2 (4.1): TILE_ST_SIZE's unit, sram_chunks() = (TILE_ST_SIZE + 1) << AREA_CHUNKS_SHIFT */

/* TILE_CONDITIONS (4.13, 8.3a): bit n = condition n. A correct program never sets one; read-only, cleared only on
 * entering HALT; any non-zero condition raises the tile's error line to C&C (6.6) */
#define TILE_COND_DRIFT      1   /* drift */
#define TILE_COND_ROUTER_OVF 2   /* router overflow */
#define TILE_COND_WE_IN_OVF  4   /* write-engine input overflow */
#define TILE_COND_RDPORT_OVF 8   /* read-port overflow */
#define TILE_COND_UNEXPECTED 0x10   /* unexpected arrival */
#define TILE_COND_TABLE_OVF  0x20   /* table request overflow */
#define TILE_COND_BUS_ERROR  0x40   /* bus error */
#define TILE_COND_ILLEGAL    0x80   /* illegal instruction */
#define TILE_COND_GATHER_OVF 0x100   /* GATHER queue overflow */
#define TILE_COND_BAD_MODE   0x200   /* bad mode */
#define TILE_COND_DONE_EARLY 0x400   /* done early */
#define TILE_COND_MASK       0x7FF   /* every condition ([31:11] reserved, read 0) */

/* packet modes (3.1) and destinations */
#define MODE_GATHER          1   /* gather request (to the tile itself) */
#define MODE_SRC             2   /* write at PTR[src] */
#define MODE_BUCKET          3   /* bucket write at PTR[bucket digit] */
#define MODE_AUG             4   /* augmented write: as mode 2, the ordinal in bits 63-32 */
#define MODE_CMEM            5   /* controller-memory write, 2 words */
#define MODE_MBOX            6   /* mailbox write */
#define MODE_REPLY           7   /* reply: one data-memory word */
#define DST_CNC              0x40
#define DST_BROADCAST        0x7E

/* read sizes and run kinds */
#define SIZE_32              1
#define SIZE_64              2
#define SIZE_128             3
#define RUN_STREAMS          0
#define RUN_GROUPS           1

/* ---- software conventions (sw/CONVENTIONS.md) ---- */
/* Commands (6.3): C&C writes the arguments, then the command word to slot 0, last.
 * Commands alternate argument blocks: even commands use slots 1-31, odd commands slots 32-63, and the
 * command word carries the parity, so the next command never overwrites the block a woken tile is
 * still reading. Command word: [31:24] type, [23] parity, [22:0] argument. */
#define CMD_PARITY_SHIFT     0x17
#define ARGS_EVEN            1   /* first argument slot of an even command */
#define ARGS_ODD             0x20   /* first argument slot of an odd command */
#define CMD_JUMP             0x4A   /* the loader's command: jump to the address in the block's first slot */
#define CMD_REPORT           0x52   /* REPORT (6.6): reply to C&C with (tile index, TILE_CONDITIONS) after a delay loop of about (me + 1) * 4 cycles */
#define SCRATCH_CHUNKS       0x8000   /* the top 128 KB of big SRAM (A7's top on 4 MB) is sort scratch (6.2) */
#define STAGE_SIZE_CHUNKS    0x4000   /* C&C's staging area: 64 KB ... */
#define STAGE_CHUNKS         0xC000   /* ... starting STAGE_CHUNKS below the top: the loader sets PTR[64] = top - STAGE_CHUNKS (6.2) */
#define CMD_TYPE(w)   ((unsigned)(w) >> 24)
#define CMD_PARITY(w) (((unsigned)(w) >> CMD_PARITY_SHIFT) & 1)
#define CMD_ARG(w)    ((unsigned)(w) & 0x7FFFFF)

#ifndef __ASSEMBLER__
#include <stdint.h>
#define MESH_REG(a) (*(volatile uint32_t *)(a))
#define TILE_STATUS             MESH_REG(TILE_STATUS_ADDR)
#define TILE_CONDITIONS         MESH_REG(TILE_CONDITIONS_ADDR)
#define ROUTER_SET_HDR          MESH_REG(ROUTER_SET_HDR_ADDR)
#define ROUTER_SET_HI           MESH_REG(ROUTER_SET_HI_ADDR)
#define ROUTER_SEND_LO          MESH_REG(ROUTER_SEND_LO_ADDR)
#define DMA_CONFIG              MESH_REG(DMA_CONFIG_ADDR)
#define DMA_PULSE               MESH_REG(DMA_PULSE_ADDR)
#define DMA_SRAM_REMAINING      MESH_REG(DMA_SRAM_REMAINING_ADDR)
#define DMA_CM_REMAINING        MESH_REG(DMA_CM_REMAINING_ADDR)
#define DMA_REPLY_REMAINING     MESH_REG(DMA_REPLY_REMAINING_ADDR)
#define DMA_RECORD_BASE_ADDRESS MESH_REG(DMA_RECORD_BASE_ADDRESS_ADDR)
#define SRAM_RD_ADDR_QUEUE      MESH_REG(SRAM_RD_ADDR_QUEUE_ADDR)
#define SRAM_RD_DEST_ADDR       MESH_REG(SRAM_RD_DEST_ADDR_ADDR)
#define READ_PORT_DEPTH     64   /* guaranteed minimum (4.3) */

#define HIST    ((volatile uint32_t *)HIST_BASE)     /* read/write */
#define PTR     ((volatile uint32_t *)PTR_BASE)      /* write-only: a load is a bus error */
#define STREAM  ((volatile uint32_t *)STREAM_BASE)   /* write-only; STREAM[2i] low word, STREAM[2i+1] high word */
#define GROUP   ((volatile uint32_t *)GROUP_BASE)    /* write-only; GROUP[2g] low, GROUP[2g+1] high */
#define MBOX   ((volatile uint32_t *)MAILBOX_BASE)
/* the command's argument block: CMD_ARGS(w)[0] is its first argument */
#define CMD_ARGS(w) (MBOX + (CMD_PARITY(w) ? ARGS_ODD : ARGS_EVEN))

/* table entries and the run */
#define STREAM_LO(src, cm) (STREAM_LO_SRC(src) | STREAM_LO_CM(cm))
#define STREAM_HI(count, d, mode, size, gap) (STREAM_HI_COUNT(count) | STREAM_HI_D(d) | STREAM_HI_MODE(mode) | STREAM_HI_SIZE(size) | STREAM_HI_GAP(gap))
#define GROUP_HI(start, t, gap) (GROUP_HI_START(start) | GROUP_HI_TM1((t) - 1) | GROUP_HI_GAP(gap))
#define DMA_CFG_RUN(kind, start, count) (DMA_CFG_KIND(kind) | DMA_CFG_START(start) | DMA_CFG_COUNT(count))
#define ROUTER_HDR(dst, mode, addr) (ROUTER_HDR_DST(dst) | ROUTER_HDR_MODE(mode) | ROUTER_HDR_ADDR(addr))
static inline void set_stream(unsigned i, uint32_t lo, uint32_t hi) { STREAM[2 * i] = lo; STREAM[2 * i + 1] = hi; }
static inline void set_group(unsigned g, uint32_t lo, uint32_t hi) { GROUP[2 * g] = lo; GROUP[2 * g + 1] = hi; }

/* status */
static inline uint32_t status(void) { return TILE_STATUS; }
/* the error conditions (4.13): 0 in a correct program; any bit is an error (TILE_COND_*) */
static inline uint32_t conditions(void) { return TILE_CONDITIONS; }
static inline unsigned tile_index(void) { return (TILE_STATUS >> TILE_ST_TILE_SHIFT) & TILE_ST_TILE_MASK; }
static inline uint32_t sram_chunks(void) { return (((TILE_STATUS >> TILE_ST_SIZE_SHIFT) & TILE_ST_SIZE_MASK) + 1) << AREA_CHUNKS_SHIFT; }
/* C&C's staging area and the sort scratch, from the device's size (6.2) */
static inline uint32_t stage_base(void) { return sram_chunks() - STAGE_CHUNKS; }
static inline uint32_t scratch_base(void) { return sram_chunks() - SCRATCH_CHUNKS; }

/* Touch STREAM, GROUP, PTR or HIST only when no engine uses them: the address generator not running (its lead-in
 * included) and ts_busy = 0 (4.10). The counters alone don't say so: arrivals can finish before this tile's own run. */
static inline void wait_tables(void) {
    while (status() & (TILE_ST_RD_RUNNING(1) | TILE_ST_TS_BUSY(1))) ;
}

/* WFI (4.11): stalls until GO or the local wake (6.3, 4.12) */
static inline void wfi(void) { __asm__ volatile ("wfi" ::: "memory"); }
/* wait_for_command (6.3): pulse done, then WFI immediately -- two back-to-back instructions; on waking,
 * read the command word in mailbox slot 0 (one load) and return it. Every wake from a command goes through
 * here, so no command word is ever overwritten unread. The done gate (4.12): from the done pulse until GO
 * only GO wakes the core, so this WFI is woken by GO and nothing else. */
static inline uint32_t wait_for_command(void) {
    __asm__ volatile ("sw %0, %1(zero)\n\twfi" :: "r"(1u << DMA_PULSE_DONE_SHIFT), "i"((int)DMA_PULSE_ADDR) : "memory");
    return MBOX[0];
}
/* start the run in DMA_CONFIG (8.2): loads the run and begins it; its first request goes out when its table
 * entries are in (4 ts_engine_latency + 2 cycles for a group run, 2 ts_engine_latency + 1 for a stream run).
 * The store a synchronised start must reach with identical code on every tile (6.3). */
static inline void start_run(void) { DMA_PULSE = DMA_PULSE_START(1); }

/* the send port (4.11): one ROUTER_SET_HDR per run of consecutive words, then ROUTER_SET_HI + ROUTER_SEND_LO per 64-bit packet */
static inline void send64(uint32_t hi, uint32_t lo) { ROUTER_SET_HI = hi; ROUTER_SEND_LO = lo; }
static inline void send32(uint32_t lo) { ROUTER_SEND_LO = lo; }
#endif /* __ASSEMBLER__ */
#endif /* MESH_H */
